    ants = []
    for x, y, dx, dy in ants_config:
        ants.append({'pos': np.array([float(x), float(y)]), 'vel': np.array([float(dx), float(dy)])})

    t = 0.0
    active_ants = list(range(len(ants)))

    while active_ants:
        min_t = float('inf')
        collision_pair = None

        for i, j in combinations(active_ants, 2):
            a1, a2 = ants[i], ants[j]
            dv = a1['vel'] - a2['vel']
            dp = a2['pos'] - a1['pos']
            if np.any(dv != 0):
                if np.abs(np.cross(dp, dv)) < 1e-9:
                    t_coll = -1.0
                    if abs(dv[0]) > 1e-9:
                        t_coll = dp[0] / dv[0]
                    elif abs(dv[1]) > 1e-9:
                        t_coll = dp[1] / dv[1]
                    if t_coll > 1e-9 and t_coll < min_t:
                        min_t = t_coll
                        collision_pair = (i, j)

        min_fall_t = float('inf')
        falling_ant = None
        for i in active_ants:
            a = ants[i]
            for dim in range(2):
                if a['vel'][dim] > 0:
                    t_fall = (N - a['pos'][dim]) / a['vel'][dim]
                elif a['vel'][dim] < 0:
                    t_fall = (0 - a['pos'][dim]) / a['vel'][dim]
                else:
                    t_fall = float('inf')
                if 0 < t_fall < min_fall_t:
                    min_fall_t = t_fall
                    falling_ant = i

        if min_t < min_fall_t:
            t += min_t
            i, j = collision_pair
            for idx in active_ants:
                ants[idx]['pos'] += ants[idx]['vel'] * min_t
            colliding_ants = [idx for idx in active_ants if np.allclose(ants[idx]['pos'], ants[i]['pos'], atol=1e-9)]
            if len(colliding_ants) == 2:
                a1, a2 = ants[colliding_ants[0]], ants[colliding_ants[1]]
                if np.allclose(a1['vel'], -a2['vel'], atol=1e-9):
                    v1, v2 = a1['vel'].copy(), a2['vel'].copy()
                    a1['vel'] = np.array([v1[1], -v1[0]])
