                    falling_ant = i
        if min_t < min_fall_t:
            t += min_t
            i, j = collision_pair
            for idx in active_ants:
                ants[idx]['pos'] += ants[idx]['vel'] * min_t
            colliding_ants = [idx for idx in active_ants if np.allclose(ants[idx]['pos'], ants[i]['pos'], atol=1e-9)]
            if len(colliding_ants) == 2:
                a1, a2 = ants[colliding_ants[0]], ants[colliding_ants[1]]
                if np.allclose(a1['vel'], -a2['vel'], atol=1e-9):
                    v1, v2 = a1['vel'].copy(), a2['vel'].copy()
                    a1['vel'] = np.array([v1[1], -v1[0]])
                    a2['vel'] = np.array([v2[1], -v2[0]])
        elif min_fall_t != float('inf'):
            t += min_fall_t
            for idx in active_ants:
                ants[idx]['pos'] += ants[idx]['vel'] * min_fall_t
            active_ants.remove(falling_ant)
        else:
            break
        if t > 2000: return None
    return t

N = 4
for _ in range(1000):
    t = solve_sim(N, random_config(N, 10))
    if t is None:
        print("Found a potential cycle!")
        break
else:
    print("No cycles found in 1000 trials with 10 ants")
